import { useCallback, useRef, useState } from 'react';
import { UiIcon } from '@/components/icons/UiIcon';
import { useDismiss } from '@/lib/uiHooks';

/**
 * "Upload Media": a button that opens the ways of adding a file. Uploading files from the computer is the one that exists; the other
 * three (from a web address, generated by AI, recorded) are listed switched off, with "Soon", so the menu says what is coming and nothing
 * in it can fail. Escape closes it and gives focus back to the button; so does a press anywhere else.
 */
export function UploadMenu({ onUploadFiles }: { onUploadFiles: () => void }) {
  const [open, setOpen] = useState(false);
  const anchor = useRef<HTMLDivElement>(null);
  const button = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useDismiss(open, close, anchor, button);

  return (
    <div className="menu-anchor" ref={anchor}>
      <button className="button button-primary" type="button" ref={button} aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen((value) => !value)}>
        <UiIcon name="upload" />
        Upload Media
        <UiIcon name="chevron" />
      </button>

      {open ? (
        <ul className="menu-popover menu-popover-end" role="menu" aria-label="Ways to add media">
          <li role="none">
            <button
              role="menuitem"
              type="button"
              className="menu-item"
              onClick={() => {
                close();
                onUploadFiles();
              }}
            >
              <UiIcon name="upload" />
              Upload Files
            </button>
          </li>
          {['Upload from URL', 'Generate with AI', 'Record Video'].map((name) => (
            <li key={name} role="none">
              <button role="menuitem" type="button" className="menu-item" disabled aria-disabled="true">
                {name}
                <span className="menu-soon">Soon</span>
              </button>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}
